import React, { useState, useEffect } from 'react';
import axios from 'axios';

export default function ManageReports() {
  const [activeTab, setActiveTab] = useState('students');
  
  // 🟢 සියලුම ව්‍යාජ සැම්පල් දත්ත සම්පූර්ණයෙන්ම ඉවත් කර හිස් ඇරේ දමන ලදි
  const [results, setResults] = useState([]);
  const [teachers, setTeachers] = useState([]);
  const [timetable, setTimetable] = useState([]);
  const [quizzes, setQuizzes] = useState([]);
  
  const [totalStudents, setTotalStudents] = useState(0);
  const [totalTeachers, setTotalTeachers] = useState(0);
  const [totalSubjects, setTotalSubjects] = useState(0);
  const [statusFilter, setStatusFilter] = useState('All');
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    // ඩේටාබේස් එකෙන් සැබෑ දත්ත ලබා ගැනීම
    axios.get('http://localhost:8082/api/student-results').then(res => setResults(Array.isArray(res.data) ? res.data : [])).catch(() => {});
    axios.get('http://localhost:8082/api/view-teachers').then(res => setTeachers(Array.isArray(res.data) ? res.data : [])).catch(() => {});
    axios.get('http://localhost:8082/api/timetable').then(res => setTimetable(Array.isArray(res.data) ? res.data : [])).catch(() => {});
    axios.get('http://localhost:8082/api/quizzes').then(res => setQuizzes(Array.isArray(res.data) ? res.data : [])).catch(() => {});

    axios.get('http://localhost:8082/api/view-students').then(res => setTotalStudents(Array.isArray(res.data) ? res.data.length : 0)).catch(() => {});
    axios.get('http://localhost:8082/api/view-teachers').then(res => setTotalTeachers(Array.isArray(res.data) ? res.data.length : 0)).catch(() => {});
    axios.get('http://localhost:8082/api/view-subjects').then(res => setTotalSubjects(Array.isArray(res.data) ? res.data.length : 0)).catch(() => {});
  }, []);

  // 🟢 ඩේටාබේස් එකෙන් එන සැබෑ දත්ත අනුව ගුරුවරුන්ගේ රිපෝට් එක ලයිව් ගණනය කිරීම
  const dynamicTeacherAnalytics = teachers.map(t => {
    const classesCount = timetable.filter(slot => slot.teacher === t.name).length;
    const quizzesCount = quizzes.filter(q => q.teacher_id === t.id).length;
    return {
      id: t.id,
      name: t.name,
      subject: t.Subject || 'General',
      classes_count: classesCount,
      quizzes_published: quizzesCount,
      status: 'Active'
    };
  });

  const filteredResults = results.filter(r => (r.student_name || '').toLowerCase().includes(searchQuery.toLowerCase()) && (statusFilter === 'All' || r.status === statusFilter));
  const filteredTeachers = dynamicTeacherAnalytics.filter(t => (t.name || '').toLowerCase().includes(searchQuery.toLowerCase()) || (t.subject || '').toLowerCase().includes(searchQuery.toLowerCase()));

  const handleDownloadPDF = () => {
    const printWindow = window.open('', '_blank');
    let title = activeTab === 'students' ? 'Student Performance Report' : 'Staff & Teacher Activity Report';
    let tableHeaders = activeTab === 'students' 
      ? `<tr><th>No.</th><th>Student Name</th><th>Grade</th><th>Subject</th><th>Quiz Title</th><th>Marks</th><th>Percentage</th><th>Status</th></tr>`
      : `<tr><th>No.</th><th>Teacher Name</th><th>Assigned Subject</th><th>Managed Classes</th><th>Quizzes Published</th><th>Status</th></tr>`;
    
    let tableRows = '';
    if (activeTab === 'students') {
      filteredResults.forEach((r, index) => {
        tableRows += `<tr><td>${index+1}</td><td>${r.student_name}</td><td>${r.grade}</td><td>${r.subject_name}</td><td>${r.quiz_title}</td><td>${r.marks_obtained}/${r.total_marks}</td><td>${((r.marks_obtained/r.total_marks)*100).toFixed(0)}%</td><td style="color:${r.status==='Pass'?'#16a34a':'#dc2626'}">${r.status}</td></tr>`;
      });
    } else {
      filteredTeachers.forEach((t, index) => {
        tableRows += `<tr><td>${index+1}</td><td style="font-weight:bold;">${t.name}</td><td>${t.subject}</td><td>${t.classes_count} Classes</td><td>${t.quizzes_published} Published</td><td style="color:#16a34a; font-weight:bold;">${t.status}</td></tr>`;
      });
    }

    printWindow.document.write(`<html><head><title>${title}</title><style>body{font-family:sans-serif;padding:40px;}h1{text-align:center;color:#15803d;border-bottom:3px solid #15803d;padding-bottom:15px;}table{width:100%;border-collapse:collapse;margin-top:20px;}th,td{border:1px solid #cbd5e1;padding:12px;text-align:left;font-size:13px;}th{background-color:#f8fafc;}</style></head><body><h1>${title.toUpperCase()}</h1><p>Generated on: ${new Date().toLocaleDateString()}</p><table><thead>${tableHeaders}</thead><tbody>${tableRows}</tbody></table><script>window.onload=function(){window.print();window.close();}</script></body></html>`);
    printWindow.document.close();
  };

  return (
    <div style={{ padding: '10px 0', fontFamily: 'sans-serif' }}>
      {/* Overview Cards */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4, 1fr)', gap: '20px', marginBottom: '25px' }}>
        <div style={{...styles.statCard, borderLeft: '4px solid #16a34a'}}><div style={styles.cardInfo}><span style={styles.cardSpan}>Total Students</span><h2 style={styles.cardH2}>{totalStudents}</h2></div><div style={{...styles.cardIcon, color: '#16a34a', backgroundColor: '#e8f5e9'}}>👨‍🎓</div></div>
        <div style={{...styles.statCard, borderLeft: '4px solid #0284c7'}}><div style={styles.cardInfo}><span style={styles.cardSpan}>Active Teachers</span><h2 style={styles.cardH2}>{totalTeachers}</h2></div><div style={{...styles.cardIcon, color: '#0284c7', backgroundColor: '#e0f2fe'}}>🧑‍🏫</div></div>
        <div style={{...styles.statCard, borderLeft: '4px solid #ea580c'}}><div style={styles.cardInfo}><span style={styles.cardSpan}>Total Subjects</span><h2 style={styles.cardH2}>{totalSubjects}</h2></div><div style={{...styles.cardIcon, color: '#ea580c', backgroundColor: '#fff7ed'}}>📚</div></div>
        <div style={{...styles.statCard, borderLeft: '4px solid #7c3aed'}}><div style={styles.cardInfo}><span style={styles.cardSpan}>Quiz Submissions</span><h2 style={styles.cardH2}>{results.length}</h2></div><div style={{...styles.cardIcon, color: '#7c3aed', backgroundColor: '#f3e8ff'}}>📊</div></div>
      </div>

      {/* Tabs */}
      <div style={{ display: 'flex', gap: '10px', marginBottom: '20px' }}>
        <button onClick={() => { setActiveTab('students'); setSearchQuery(''); }} style={{...styles.tabBtn, backgroundColor: activeTab === 'students' ? '#15803d' : '#ffffff', color: activeTab === 'students' ? '#ffffff' : '#475569' }}>👨‍🎓 Student Academic Performance</button>
        <button onClick={() => { setActiveTab('teachers'); setSearchQuery(''); }} style={{...styles.tabBtn, backgroundColor: activeTab === 'teachers' ? '#15803d' : '#ffffff', color: activeTab === 'teachers' ? '#ffffff' : '#475569' }}>🧑‍🏫 Staff Activity & Teacher Analytics</button>
      </div>

      {/* Table Container */}
      <div style={{ backgroundColor: '#fff', padding: '25px', borderRadius: '16px', boxShadow: '0 4px 12px rgba(0,0,0,0.02)' }}>
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', marginBottom: '20px' }}>
          <h3 style={{ margin: 0, color: '#1e293b', fontSize: '16px', fontWeight: 'bold' }}>{activeTab === 'students' ? '📝 Student Evaluation Data Matrix' : '🏢 Institutional Faculty Operational Logs'}</h3>
          
          <div style={{ display: 'flex', gap: '12px' }}>
            <input type="text" placeholder={activeTab === 'students' ? "Search student..." : "Search teacher or subject..."} value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} style={styles.filterInput} />
            
            {activeTab === 'students' && (
              <select value={statusFilter} onChange={(e) => setStatusFilter(e.target.value)} style={styles.filterSelect}>
                <option value="All">All Status</option>
                <option value="Pass">Passed Only</option>
                <option value="Fail">Failed Only</option>
              </select>
            )}
            <button onClick={handleDownloadPDF} style={styles.pdfBtn}>📋 Download PDF</button>
          </div>
        </div>

        {activeTab === 'students' ? (
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
                <th style={styles.th}>No.</th><th style={styles.th}>Student Name</th><th style={styles.th}>Grade</th><th style={styles.th}>Subject</th><th style={styles.th}>Quiz Title</th><th style={styles.th}>Marks</th><th style={styles.th}>Percentage</th><th style={styles.th}>Status</th>
              </tr>
            </thead>
            <tbody>
              {filteredResults.length > 0 ? filteredResults.map((r, index) => (
                <tr key={index} style={{ borderBottom: '1px solid #f1f5f9' }}>
                  <td style={styles.td}>{index + 1}</td><td style={{...styles.td, fontWeight: 'bold'}}>{r.student_name}</td><td style={styles.td}>{r.grade}</td><td style={{...styles.td, color: '#0284c7'}}>{r.subject_name}</td><td style={styles.td}>{r.quiz_title}</td><td style={styles.td}>{r.marks_obtained} / {r.total_marks}</td><td style={styles.td}>{((r.marks_obtained/r.total_marks)*100).toFixed(0)}%</td>
                  <td style={styles.td}><span style={{ padding: '4px 10px', borderRadius: '12px', fontSize: '11px', fontWeight: 'bold', backgroundColor: r.status === 'Pass' ? '#dcfce7' : '#fee2e2', color: r.status === 'Pass' ? '#15803d' : '#b91c1c' }}>{r.status}</span></td>
                </tr>
              )) : (
                <tr><td colSpan="8" style={{ padding: '20px', textAlign: 'center', color: '#94a3b8' }}>No evaluation records found.</td></tr>
              )}
            </tbody>
          </table>
        ) : (
          <table style={{ width: '100%', borderCollapse: 'collapse' }}>
            <thead>
              <tr style={{ backgroundColor: '#f8fafc', borderBottom: '2px solid #e2e8f0' }}>
                <th style={styles.th}>No.</th><th style={styles.th}>Teacher Name</th><th style={styles.th}>Assigned Core Subject</th><th style={styles.th}>Managed Classes</th><th style={styles.th}>Quizzes Published</th><th style={styles.th}>Status</th>
              </tr>
            </thead>
            <tbody>
              {filteredTeachers.length > 0 ? filteredTeachers.map((t, index) => (
                <tr key={index} style={{ borderBottom: '1px solid #f1f5f9' }}>
                  <td style={styles.td}>{index + 1}</td><td style={{...styles.td, fontWeight: 'bold'}}>{t.name}</td><td style={{...styles.td, color: '#ea580c'}}>{t.subject}</td><td style={styles.td}>{t.classes_count} Active Classes</td><td style={styles.td}>{t.quizzes_published} Quizzes</td>
                  <td style={styles.td}><span style={{ padding: '4px 10px', borderRadius: '12px', fontSize: '11px', fontWeight: 'bold', backgroundColor: '#dcfce7', color: '#15803d' }}>{t.status}</span></td>
                </tr>
              )) : (
                <tr><td colSpan="6" style={{ padding: '20px', textAlign: 'center', color: '#94a3b8' }}>No teacher operational records found.</td></tr>
              )}
            </tbody>
          </table>
        )}
      </div>
    </div>
  );
}

const styles = {
  statCard: { backgroundColor: 'white', padding: '20px', borderRadius: '16px', boxShadow: '0 4px 12px rgba(0,0,0,0.02)', display: 'flex', justifyContent: 'space-between', alignItems: 'center' },
  cardInfo: { display: 'flex', flexDirection: 'column', gap: '4px' },
  cardSpan: { fontSize: '12px', color: '#64748b' },
  cardH2: { margin: 0, fontSize: '24px', color: '#1e293b', fontWeight: '800' },
  cardIcon: { fontSize: '22px', padding: '10px', borderRadius: '12px', display: 'flex', alignItems: 'center', justifyContent: 'center' },
  tabBtn: { padding: '10px 18px', border: '1px solid #cbd5e1', borderRadius: '8px', cursor: 'pointer', fontSize: '13px', fontWeight: 'bold' },
  th: { padding: '12px 10px', color: '#64748b', fontWeight: 'bold', fontSize: '13px', textAlign: 'left' },
  td: { padding: '14px 10px', fontSize: '13px', color: '#334155' },
  filterInput: { padding: '8px 12px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '13px', width: '200px' },
  filterSelect: { padding: '8px 12px', borderRadius: '8px', border: '1px solid #cbd5e1', fontSize: '13px', backgroundColor: 'white' },
  pdfBtn: { padding: '8px 15px', backgroundColor: '#b91c1c', color: 'white', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold', fontSize: '13px' }
};
